package worker
import("context";"path/filepath";"testing";"time";"github.com/11DingKing/silvercare-coordination/internal/clock";"github.com/11DingKing/silvercare-coordination/internal/domain";storesqlite "github.com/11DingKing/silvercare-coordination/internal/store/sqlite")
func TestFailedIdempotencyCleanupPreservesBatch(t *testing.T){ctx:=context.Background();now:=time.Date(2026,8,24,8,0,0,0,time.UTC);repo,e:=storesqlite.Open(ctx,filepath.Join(t.TempDir(),"i.db"));if e!=nil{t.Fatal(e)};defer repo.Close();repo.Migrate(ctx);repo.EnsureDistrict(ctx,nil,storesqlite.DistrictBudget{ID:"d",Name:"街道",Timezone:"Asia/Shanghai",MonthlyCents:1000000,Version:1,CreatedAt:now,UpdatedAt:now});exec:=func(q string,a ...any){if _,e:=repo.DB().ExecContext(ctx,q,a...);e!=nil{t.Fatal(e)}};ts:=now.Add(-2*time.Hour).Format(time.RFC3339Nano);for _,k:=range []string{"k1","k2"}{exec(`INSERT INTO idempotency_records(district_id,actor_id,operation,idempotency_key,request_hash,response_code,response_json,state,expires_at,created_at,updated_at) VALUES('d','u','op',?,?,200,'{}','completed',?,?,?)`,k,k,ts,ts,ts)};exec(`CREATE TRIGGER reject_second BEFORE DELETE ON idempotency_records WHEN OLD.idempotency_key='k2' BEGIN SELECT RAISE(ABORT,'second failure'); END`);m:=NewMaintenance(repo,clock.NewFixed(now));if e:=m.CleanupIdempotency(ctx,domain.WorkerJob{});e==nil{t.Fatal("expected failure")};var n int;repo.DB().QueryRowContext(ctx,"SELECT COUNT(*) FROM idempotency_records WHERE idempotency_key='k1'").Scan(&n);if n!=1{t.Errorf("first record deleted=%d",n)}}
